SELECT 
FROM voucher


        AND voucher_id = #{voucherId}


        AND ([code]) LIKE ('%' + (#{code}) + '%')


        AND voucher_type = #{voucherType}


        AND min_spend = #{minSpend}


ORDER BY create_at DESC
OFFSET #{offset} ROWS FETCH NEXT #{size} ROWS ONLY

SELECT COUNT(voucher_id)
FROM voucher


        AND voucher_id = #{voucherId}


        AND ([code]) LIKE ('%' + (#{code}) + '%')


        AND voucher_type = #{voucherType}


        AND min_spend = #{minSpend}
